codeExamples.code:
-- Compact only today's partition to avoid rewriting cold data
OPTIMIZE sales
WHERE event_date = '2026-06-20';

-- Inspect the result metrics (files added/removed)
DESCRIBE HISTORY sales LIMIT 1;

-- Optionally set a target file size for this table
ALTER TABLE sales SET TBLPROPERTIES (
  'delta.targetFileSize' = '256mb'
);
